import re

from .models import Item, Order
from .units import g_to_kg, normalize_kg

ALLOWED = ("sku", "weight_g", "weight_kg", "qty")
_DIGITS = re.compile(r"[0-9]+")


def _split_lines(text):
    """Lines end with \\n or \\r\\n; the last line may have no line end."""
    lines = text.split("\n")
    return [line[:-1] if line.endswith("\r") else line for line in lines]


def _header(lines):
    if not lines or not lines[0]:
        raise ValueError("empty file")
    names = [cell.strip(" ") for cell in lines[0].split(",")]
    for name in names:
        if name not in ALLOWED:
            raise ValueError(f"unknown column: {name!r}")
    seen = set()
    for name in names:
        if name in seen:
            raise ValueError(f"duplicate column: {name!r}")
        seen.add(name)
    if "sku" not in names:
        raise ValueError("missing column: 'sku'")
    if "weight_g" in names and "weight_kg" in names:
        raise ValueError("both weight_g and weight_kg")
    if "weight_g" not in names and "weight_kg" not in names:
        raise ValueError("missing weight column")
    return names


def _weight(row):
    if "weight_g" in row:
        cell = row["weight_g"]
        if not _DIGITS.fullmatch(cell):
            raise ValueError(f"invalid weight: {cell!r}")
        return g_to_kg(int(cell))
    return normalize_kg(row["weight_kg"])


def parse_csv(text):
    lines = _split_lines(text)
    names = _header(lines)
    order = Order()
    for number, line in enumerate(lines[1:], start=2):
        if not line:
            continue
        cells = line.split(",")
        if len(cells) != len(names):
            raise ValueError(f"row {number}: wrong number of cells")
        row = dict(zip(names, cells))
        weight = _weight(row)
        qty = row.get("qty", "1")
        if not _DIGITS.fullmatch(qty) or int(qty) < 1:
            raise ValueError(f"invalid quantity: {qty!r}")
        order.add(Item(row["sku"], weight, int(qty)))
    return order

