"""Audit log: one JSON object per line. Version 1 entries hold grams, version 2 entries hold kilograms.
See docs/FORMATS.md."""
import json

from .units import g_to_kg, g_to_kg as _g_to_kg, kg_to_g, normalize_kg


def write_entry(path, event, sku, weight_kg, qty=1):
    weight = normalize_kg(weight_kg)
    entry = {"v": 2, "event": event, "sku": sku, "weight_kg": weight, "qty": qty}
    with open(path, "a", encoding="utf-8") as handle:
        handle.write(json.dumps(entry, sort_keys=True) + "\n")


def _version(entry):
    version = entry.get("v", 1)
    if type(version) is not int or version not in (1, 2):
        raise ValueError(f"unsupported log version: {version!r}")
    return version


def _convert(entry):
    version = _version(entry)
    converted = dict(entry)
    if version == 1:
        if "weight_g" in entry:
            converted["weight_kg"] = g_to_kg(entry["weight_g"])
            del converted["weight_g"]
    elif "weight_kg" in entry:
        converted["weight_kg"] = normalize_kg(entry["weight_kg"])
    converted["v"] = 2
    return converted


def read_entries(path):
    entries = []
    with open(path, encoding="utf-8") as handle:
        for line in handle:
            if not line.strip():
                continue
            entries.append(_convert(json.loads(line)))
    return entries


def total_added_kg(path):
    total = sum(
        kg_to_g(e["weight_kg"]) * e.get("qty", 1)
        for e in read_entries(path)
        if e.get("event") == "add" and "weight_kg" in e
    )
    return g_to_kg(total)

"""Weight band surcharges, read from the generated table data/surcharges.json."""
import json
from pathlib import Path

from .units import to_grams

DEFAULT_TABLE = Path(__file__).with_name("data") / "surcharges.json"


def load(path=None):
    with open(path or DEFAULT_TABLE, encoding="utf-8") as handle:
        data = json.load(handle)
    if data.get("schema") != 1:
        raise ValueError(f"unsupported schema: {data.get('schema')!r}")
    bands = [{"max_g": to_grams(band["max_g"]), "cents": band["cents"]} for band in data["bands"]]
    bands.sort(key=lambda band: band["max_g"])
    return {"bands": bands, "over_cents": data["over_cents"]}


def cents_for(weight_g, table=None):
    """Surcharge of the first band whose limit is at least the weight; else the over-limit surcharge."""
    table = load() if table is None else table
    for band in table["bands"]:
        if weight_g <= band["max_g"]:
            return band["cents"]
    return table["over_cents"]

