"""Plugin registry: the extras listed in plugins.json are loaded by their dotted module name."""
import importlib
import json
from pathlib import Path

from .units import g_to_kg, normalize_kg

DEFAULT_CONFIG = Path(__file__).with_name("plugins.json")


def _is_version(value, known):
    return type(value) is int and value in known


def _options(schema, raw):
    """Options as make() receives them: weights are canonical kilogram strings under _kg keys."""
    options = {}
    for key, value in raw.items():
        if schema == 1 and key.endswith("_g"):
            options[key[:-2] + "_kg"] = g_to_kg(value)
        elif schema == 2 and key.endswith("_kg"):
            options[key] = normalize_kg(value)
        else:
            options[key] = value
    return options


def load(path=None):
    with open(path or DEFAULT_CONFIG, encoding="utf-8") as handle:
        data = json.load(handle)
    schema = data.get("schema")
    if not (_is_version(schema, (1,)) or _is_version(schema, (2,))):
        raise ValueError(f"unsupported schema: {schema!r}")
    plugins = []
    for entry in data["plugins"]:
        options = _options(schema, dict(entry.get("options", {})))
        plugins.append(importlib.import_module(entry["module"]).make(options))
    return plugins


def extras_cents(order, plugins=None):
    plugins = load() if plugins is None else plugins
    return sum(plugin.surcharge_cents(order) for plugin in plugins)

