from ..packing import split_parcels
from ..units import kg_to_g

UNIT = "kg"


class Bulky:
    def __init__(self, over, cents):
        self.over = over
        self.cents = cents

    def surcharge_cents(self, order):
        limit = kg_to_g(self.over)
        heavy = [p for p in split_parcels(order) if kg_to_g(getattr(p, "weight_" + UNIT)) > limit]
        return len(heavy) * self.cents


def make(options):
    return Bulky(options["parcel_over_" + UNIT], options["cents"])

